'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const d = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

(async () => {
  // Repeated invalidations: A, B detached; old completions must not detach C or store.
  {
    const gates = [d(), d(), d()]; let n = 0;
    const c = createCache({ now: () => 0, load: () => gates[n++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick(); c.invalidate('k');
    const cc = c.get('k'); await tick();
    gates[0].resolve('A'); assert.equal(await a, 'A');
    gates[1].resolve('B'); assert.equal(await b, 'B');
    assert.equal(c.get('k') === cc || n === 3, true);
    assert.equal(n, 3, 'C still joined');
    gates[2].resolve('C'); assert.equal(await cc, 'C');
    assert.equal(await c.get('k'), 'C'); assert.equal(n, 3);
  }
  // Rejection: same reason to all waiters, not cached, retry allowed; sync throw too.
  {
    let n = 0; const reason = { nonError: true };
    const c = createCache({ now: () => 0, load: () => { n++; if (n === 1) throw reason; if (n === 2) return Promise.reject(reason); return 'ok'; } });
    const r1 = c.get('k'), r2 = c.get('k');
    await assert.rejects(r1, e => e === reason); await assert.rejects(r2, e => e === reason);
    await assert.rejects(c.get('k'), e => e === reason);
    assert.equal(await c.get('k'), 'ok'); assert.equal(n, 3);
  }
  // Detached rejection must not detach newer flight.
  {
    const g = [d(), d()]; let n = 0;
    const c = createCache({ now: () => 0, load: () => g[n++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    g[0].reject(new Error('x')); await assert.rejects(a);
    c.get('k'); await tick(); assert.equal(n, 2);
    g[1].resolve('B'); assert.equal(await b, 'B');
  }
  // set wins; old load completion does not restart TTL; expiry starts new load.
  {
    let t = 0; const g = d(); let n = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++n === 1 ? g.promise : 'new') });
    const a = c.get('k'); await tick();
    c.set('k', 'S'); assert.equal(await c.get('k'), 'S');
    t = 5; g.resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'new'); assert.equal(n, 2);
  }
  // TTL starts at commit; exact expiry boundary.
  {
    let t = 0; const g = d(); let n = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++n === 1 ? g.promise : 'v2') });
    const a = c.get('k'); await tick(); t = 100; g.resolve('v1'); await a;
    t = 109; assert.equal(await c.get('k'), 'v1');
    t = 110; assert.equal(await c.get('k'), 'v2'); assert.equal(n, 2);
  }
  // ttl 0 dedups unsettled but never reuses.
  {
    let n = 0; const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++n });
    const [x, y] = [c.get('k'), c.get('k')]; assert.equal(await x, 1); assert.equal(await y, 1);
    assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  // load invalidates own key synchronously; own-key read joins flight; undefined values.
  {
    let n = 0, c, inner;
    c = createCache({ now: () => 0, load: k => { n++; if (n === 1) { inner = c.get(k); c.invalidate(k); return 'first'; } return undefined; } });
    const a = c.get('k'); assert.equal(await a, 'first'); assert.equal(inner, a);
    assert.equal(await c.get('k'), undefined); assert.equal(n, 2);
    assert.equal(await c.get('k'), undefined); assert.equal(n, 2);
  }
  // clear detaches all.
  {
    const g = d(); let n = 0;
    const c = createCache({ now: () => 0, load: () => (++n === 1 ? g.promise : 'fresh') });
    const a = c.get('k'); await tick(); c.clear(); const b = c.get('k');
    g.resolve('stale'); assert.equal(await a, 'stale'); assert.equal(await b, 'fresh');
    assert.equal(await c.get('k'), 'fresh'); assert.equal(n, 2);
  }
  console.log('all checks passed');
})().catch(e => { console.error(e); process.exit(1); });

